typedef struct Node {
    char data;
    struct Node *left, *right;
} Node;

void printExpr(const Node *p, int isRoot) {
    if (p == NULL) return;
    int nonLeaf = p->left != NULL || p->right != NULL;
    if (!isRoot && nonLeaf) putchar('(');
    printExpr(p->left, 0);
    putchar(p->data);
    printExpr(p->right, 0);
    if (!isRoot && nonLeaf) putchar(')');
}
/* #include <stdio.h>；调用 printExpr(root, 1)。
   本例结点 data 为单字符，二元或右孩子承载的一元表达式。 */

int partition(int a[], int low, int high) {
    int pivot = a[low];
    while (low < high) {
        while (low < high && a[high] >= pivot) --high;
        a[low] = a[high];
        while (low < high && a[low] <= pivot) ++low;
        a[high] = a[low];
    }
    a[low] = pivot;
    return low;
}
void quickSort(int a[], int low, int high) {
    if (low >= high) return;
    int p = partition(a, low, high);
    quickSort(a, low, p - 1);
    quickSort(a, p + 1, high);
}
/* 调用 quickSort(a, 0, n-1)。
   此首元素枢轴实现平均 O(n log n)，最坏 O(n²)；
   递归栈平均 O(log n)，最坏 O(n)。 */
